table netdev syswarden_hw_drop {
    set syswarden_blacklist { type ipv4_addr; flags interval; auto-merge; }
    set syswarden_whitelist { type ipv4_addr; flags interval; auto-merge; }
    set syswarden_whitelist6 { type ipv6_addr; flags interval; auto-merge; }
    chain ingress_frontline {
        type filter hook ingress device "swv0" priority -500; policy accept;

        # Absolute whitelist bypass at NIC level (O(1) Radix Tree Lookup optimization)
        ip saddr @syswarden_whitelist accept
        ip6 saddr @syswarden_whitelist6 accept

        # Stateless Layer 4 Structural Anomaly Mitigation (Bypasses Stateful Engine)
        ip protocol tcp tcp flags & (fin|syn|rst|psh|ack|urg) == 0 counter drop
        ip protocol tcp tcp flags & (fin|syn|rst|psh|ack|urg) == fin|syn|rst|psh|ack|urg counter drop
        ip protocol tcp tcp flags & (fin|syn) == fin|syn counter drop
        ip protocol tcp tcp flags & (syn|rst) == syn|rst counter drop
        # Hardware Drops with SIEM Logging (Rate-Limited to prevent CPU/IO exhaustion)
        ip saddr @syswarden_blacklist limit rate 2/second log prefix "[SysWarden-BLOCK] "
        ip saddr @syswarden_blacklist drop
    }
}

